import pathlib,json,hashlib
R=pathlib.Path('outputs/K5_EVALUATION_20260919'); rows=[]
D=json.loads((R/'donor_traces/DELTA.json').read_text());D={(r['split'],r['font'],r['cp'],r['k']):r['donors'] for r in D}
def asset(p):return 'assets/'+hashlib.sha256(p.encode()).hexdigest()+'.png'
for s in ['train','val','test']:
 a=json.loads((R/'K5-A'/s/'metrics.json').read_text())['rows'];b={(r['font'],r['cp'],r['k']):r for r in json.loads((R/'K5-B'/s/'metrics.json').read_text())['rows']}
 for r in a:
  t=b[r['font'],r['cp'],r['k']];ds=D[s,r['font'],r['cp'],r['k']]
  rows.append(dict(split=s,font=r['font'],cp=r['cp'],shot=r['k'],script=r['script'],gt=asset(r['target']),refs=[asset(x) for x in r['refs_paths']],A=f"K5-A/{s}/{r['png']}",B=f"K5-B/{s}/{t['png']}",l1=[r['l1'],t['l1']],ssim=[r['ssim'],t['ssim']],donors=[dict(font=d['font'],alpha=d['alpha'],image=asset(d['path'])) for d in ds]))
html='''<!doctype html><meta charset="utf-8"><title>K5 A/B视觉复核</title><style>body{font:16px system-ui;background:#f4f5f6;color:#17212c;margin:24px}header{position:sticky;top:0;background:#f4f5f6;padding:12px;z-index:2}select,input,button{padding:8px;margin:4px}article{background:white;padding:18px;margin:16px 0;border-radius:10px}.images{display:flex;gap:18px;flex-wrap:wrap}figure{margin:8px}img{width:144px;height:144px;object-fit:contain;image-rendering:pixelated}.small img{width:64px;height:64px}.small{display:flex;flex-wrap:wrap;gap:8px}figcaption{font-size:12px;max-width:180px;overflow-wrap:anywhere}summary{cursor:pointer}</style><header><h1>K5-A / K5-B · 10k EMA</h1><p>相同V2训练bank与weight-only排除。L1是生成PNG误差，不是训练loss。候选缩略图是donor原图，不是Delta特征可视化。</p><select id="split"><option>train</option><option>val</option><option>test</option></select><select id="shot"><option>1</option><option>2</option><option selected>4</option><option>8</option></select><select id="script"><option value="">全部script</option><option>western</option><option>kana</option><option>bopomofo</option></select><input id="font" placeholder="字体名筛选"><input id="cp" placeholder="字符或u0041"><button id="prev">上一页</button><button id="next">下一页</button><span id="count"></span></header><main id="main"></main><script>const rows=__DATA__;let page=0;const $=x=>document.getElementById(x);function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function fig(p,label){return `<figure><a href="${esc(p)}" target="_blank"><img loading="lazy" src="${esc(p)}"></a><figcaption>${esc(label)}</figcaption></figure>`}function render(){let cp=$('cp').value.trim();if([...cp].length===1)cp='u'+cp.codePointAt(0).toString(16).toUpperCase().padStart(4,'0');let rr=rows.filter(r=>r.split==$('split').value&&r.shot==+$('shot').value&&(!$('script').value||r.script==$('script').value)&&r.font.toLowerCase().includes($('font').value.toLowerCase())&&(!cp||r.cp.toLowerCase().includes(cp.toLowerCase())));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(rr.length/6)-1)));$('count').textContent=`${rr.length}条，第${page+1}页`;$('main').innerHTML=rr.slice(page*6,page*6+6).map(r=>`<article><h3>${esc(r.font)} · ${esc(r.cp)} · ${String.fromCodePoint(parseInt(r.cp.slice(1),16))} · ${r.shot}shot</h3><div class="images">${fig(r.gt,'GT')}${fig(r.A,`K5-A L1=${r.l1[0].toFixed(5)} SSIM=${r.ssim[0].toFixed(5)}`)}${fig(r.B,`K5-B L1=${r.l1[1].toFixed(5)} SSIM=${r.ssim[1].toFixed(5)}`)}</div><div class="small">${r.refs.map((p,i)=>fig(p,'参考 '+(i+1))).join('')}</div><details><summary>相同Top10 donor及初始alpha</summary><div class="small">${r.donors.map(d=>fig(d.image,`${d.font} α=${d.alpha.toFixed(4)}`)).join('')}</div></details></article>`).join('')}for(let id of ['split','shot','script','font','cp'])$(id).onchange=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};render();</script>'''
(R/'index.html').write_text(html.replace('__DATA__',json.dumps(rows,ensure_ascii=False)));print(len(rows))
